import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"引力模型","description":"","frontmatter":{"title":"引力模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gravity-model.md","filePath":"econ/gravity-model.md","lastUpdated":1789023840000}'),_={name:"econ/gravity-model.md"};function m(c,a,h,A,u,B){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="引力模型" tabindex="-1">引力模型 <a class="header-anchor" href="#引力模型" aria-label="Permalink to &quot;引力模型&quot;">​</a></h1><div class="epigraph"><p>双边贸易随经济规模升、随距离与边界降；这不是天体力学的比喻课，而是支出份额与市场进入成本加总之后的会计。</p><footer>—— Tinbergen 经验引力；Anderson and van Wincoop, Gravity with Gravitas, AER 2003</footer></div><p><a href="/econ/melitz-heterogeneous-firms">上一课</a>在企业层给出选择。本课把双边流量写成可估计的引力。Eaton–Kortum 下一课给李嘉图微观基础的另一种加总。本课钉：结构引力与多边阻力，禁止把距离弹性当因果魔法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经验上 \\(X_{ij}\\propto Y_i Y_j/\\mathrm{dist}_{ij}^\\zeta\\)。Tinbergen 当描述。Anderson–van Wincoop：CES 需求下，双边出口还依赖<strong>多边阻力</strong>——\\(i\\) 进入所有市场的成本、\\(j\\) 从所有来源购买的成本。漏掉它们，距离与边界的系数有偏（边境之谜被夸大）。缺口不是再讲 Melitz 门槛，而是：加总之后，任何产生 CES 或类似支出份额的模型都会长出引力；估计必须处理多边阻力（固定效应或显式价格指数）。</p><p><span class="marginnote">Head–Mayer 综述：引力是贸易经验的骨干。PPML（Santos Silva–Tenreyro）处理零贸易与异方差，OLS 对数会扔零、且 Jensen 不等式偏误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>结构：\\(\\ln X_{ij}=\\ln S_i+\\ln M_j+\\ln \\tau_{ij}^{1-\\sigma}+\\varepsilon_{ij}\\)，\\(S_i,M_j\\) 用进出口固定效应吸收。\\(\\tau_{ij}\\) 含距离、边界、语言、关税、协定。因果：关税与协定仍要识别（后课 WTO、China shock），引力方程本身先是均衡加总。一般均衡反事实：改 \\(\\tau\\)，重解所有多边阻力（Dekle–Eaton–Kortum 精确帽子代数），不是只看双边偏效应。</p>',8)),(e(),s(E,null,{default:i(()=>[p(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CES%5B%22%E6%94%AF%E5%87%BA%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20GRV%5B%22%E5%8F%8C%E8%BE%B9%20X_ij%22%5D%0A%20%20SIZE%5B%22%E8%A7%84%E6%A8%A1%20Y%22%5D%20--%3E%20GRV%0A%20%20TAU%5B%22%E8%B4%B8%E6%98%93%E6%88%90%E6%9C%AC%20%CF%84%22%5D%20--%3E%20GRV%0A%20%20MR%5B%22%E5%A4%9A%E8%BE%B9%E9%98%BB%E5%8A%9B%22%5D%20--%3E%20BIAS%5B%22%E6%BC%8F%E6%8E%89%E5%88%99%E8%B7%9D%E7%A6%BB%2F%E8%BE%B9%E5%A2%83%E5%81%8F%22%5D%0A%20%20FE%5B%22%E8%BF%9B%E5%87%BA%E5%8F%A3%20FE%22%5D%20--%3E%20MR%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与计量：国家–产品–时间面板上的政策可以用 DiD，但必须与多边阻力共存（三元固定效应）。本课不重写交错 DiD。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是份额。\\(j\\) 的支出在来源 \\(i\\) 上的份额随相对 \\(\\tau_{ij}\\) 与相对价格变。距离进入 \\(\\tau\\)，所以流量随距离降。规模进入支出与供给能力。零贸易：Melitz 选择使部分 \\(ij\\) 对为零，引力在广延边际也成立（Helpman–Melitz–Rubinstein）。EK 下一课用极值生产率抽签给出另一套闭式份额。</p><p>边境效应大：可以是真实政策壁垒、可以是可加贸易成本在短距离上更显眼、可以是多边阻力误设。Anderson–van Wincoop 显示：正确计入阻力后，美加边境仍在，但小于朴素回归。</p><p><span class="marginnote">不要把引力写成牛顿定律。\\(\\zeta\\) 随 \\(\\sigma\\) 与 \\(\\tau\\) 的函数形式变。结构反事实要的是贸易弹性 \\(\\sigma-1\\)，不是某一个距离系数的永恒值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 FTA 的系数当成福利。福利要进关税与条款课的一般均衡。下一课 Eaton–Kortum 把李嘉图随机化，引力从极值分布长出。不要用引力吞并量化栏的运费或提单微观结构。</p><p>后课默认：双边流量用带多边阻力的引力；对数 OLS 丢零是问题；政策反事实要重解阻力，不是读一个 \\(\\tau\\) 系数当充分统计。企业选择与引力加总兼容。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>引力：规模促进、距离与壁垒抑制；来自支出份额加总。</li><li>多边阻力必须进估计，否则边境与距离偏。</li><li>PPML 与固定效应处理零与阻力。</li><li>反事实是一般均衡帽子代数，不是偏系数。</li><li>出处：Tinbergen；Anderson and van Wincoop, <em>AER</em> 2003；Santos Silva and Tenreyro；Head and Mayer。</li></ul>',10))])}const f=o(_,[["render",m]]);export{T as __pageData,f as default};
